import{c as t,Q as n,j as i,m as s}from"./chunks/framework.g_l1frA7.js";const u=JSON.parse('{"title":"Conscious Spending","description":"","frontmatter":{},"headers":[],"relativePath":"framework/conscious-spending.md","filePath":"framework/conscious-spending.md","lastUpdated":null}'),o={name:"framework/conscious-spending.md"};function a(r,e,l,g,d,c){return n(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="conscious-spending" tabindex="-1">Conscious Spending <a class="header-anchor" href="#conscious-spending" aria-label="Permalink to &quot;Conscious Spending&quot;">​</a></h1><blockquote><p>Tag every dollar as a Need, Want, Saving, or Investment — then look at the allocation. — <em>Sethi</em></p></blockquote><h2 id="spending-types" tabindex="-1">Spending types <a class="header-anchor" href="#spending-types" aria-label="Permalink to &quot;Spending types&quot;">​</a></h2><p>Each category in FinSight carries a <code>spending_type</code>:</p><ul><li><strong>Need</strong> — housing, utilities, groceries</li><li><strong>Want</strong> — dining, shopping, travel</li><li><strong>Saving</strong> — emergency fund, sinking funds</li><li><strong>Investment</strong> — retirement, brokerage, education</li></ul><p>Set it per category in <strong>Categories</strong>. The Budget allocation donut and <code>wellness_context</code> both read it.</p><h2 id="why-it-matters" tabindex="-1">Why it matters <a class="header-anchor" href="#why-it-matters" aria-label="Permalink to &quot;Why it matters&quot;">​</a></h2><p>When every dollar has a type, drift becomes visible: wants quietly eating wants is a pattern, not a feeling. FinSight flags when wants exceed needs or when saving falls below wants without comment.</p><h2 id="using-it" tabindex="-1">Using it <a class="header-anchor" href="#using-it" aria-label="Permalink to &quot;Using it&quot;">​</a></h2><ul><li><strong>Budget</strong> — the donut updates live as you change envelopes. If Saving + Investment &lt; 10%, the screen suggests a shift.</li><li><strong>Categories</strong> — review the type quarterly; moving “Dining” from Want to Need changes the Copilot’s warnings and the wellness score.</li><li><strong>Copilot</strong> — “How is my allocation this month?” returns the donut figures with the same source as Budget.</li></ul><p>Conscious spending is not austerity. It is intentionality — the same income, fewer regrets.</p>',11)])])}const p=t(o,[["render",a]]);export{u as __pageData,p as default};
